// ============================================================
//  1. Context Retrieval (RAG)
// ============================================================
async function retrieveRagContext(companyId = null) {
  try {
    let candQuery = supabase.from('candidates').select('id, name, email, phone, structured_data, ocr_confidence, created_at, source_file');
    let jobQuery = supabase.from('job_descriptions').select('id, title, description_text, required_skills, preferred_skills, department, created_at');
    let rankQuery = supabase.from('rankings').select('job_id, candidate_id, overall_score, similarity_score, skill_match_score, rank_position, explanation');

    if (companyId) {
      candQuery = candQuery.or(`company_id.eq.${companyId},company_id.is.null`);
      jobQuery = jobQuery.or(`company_id.eq.${companyId},created_by.is.null`);
    }

    const [candRes, jobRes, rankRes] = await Promise.all([
      candQuery.limit(50),
      jobQuery.limit(20),
      rankQuery.limit(100),
    ]);

    const candidates = candRes.data || [];
    const jobs = jobRes.data || [];
    const rankings = rankRes.data || [];

    const jobMap = Object.fromEntries(jobs.map((j) => [j.id, j]));
    const candMap = Object.fromEntries(candidates.map((c) => [c.id, c]));

    const candidateRankings = {};
    rankings.forEach((r) => {
      if (!candidateRankings[r.candidate_id]) candidateRankings[r.candidate_id] = [];
      candidateRankings[r.candidate_id].push(r);
    });

    const candidatesWithRankings = candidates.map((c) => ({
      ...c,
      rankings: candidateRankings[c.id] || [],
      bestRank: candidateRankings[c.id]?.sort((a, b) => b.overall_score - a.overall_score)[0] || null,
    }));

    const formattedCandidates = candidatesWithRankings.map((c, i) => {
      const sd = c.structured_data || {};
      const skills = sd.all_skills || sd.skills?.technical || [];
      const exp = sd.total_experience_years ?? sd.years_experience ?? 0;
      const edu = sd.education?.degree || sd.education_history?.[0]?.degree || 'N/A';
      const rank = c.bestRank ? `Ranked #${c.bestRank.rank_position} (${Math.round(c.bestRank.overall_score * 100)}% match)` : 'Not ranked yet';
      return `${i + 1}. Name: ${c.name || 'Candidate'} | Email: ${c.email || 'N/A'} | Experience: ${exp} yrs | Degree: ${edu} | Skills: ${Array.isArray(skills) ? skills.join(', ') : 'N/A'} | ${rank}`;
    }).join('\n');

    const formattedJobs = jobs.map((j, i) => {
      const reqS = Array.isArray(j.required_skills) ? j.required_skills.join(', ') : 'N/A';
      const prefS = Array.isArray(j.preferred_skills) ? j.preferred_skills.join(', ') : 'N/A';
      return `${i + 1}. Job Title: ${j.title} | Department: ${j.department || 'N/A'} | Required: ${reqS} | Preferred: ${prefS}`;
    }).join('\n');

    const formattedRankings = rankings.slice(0, 20).map((r) => {
      const jobTitle = jobMap[r.job_id]?.title || r.job_id;
      const candidateName = candMap[r.candidate_id]?.name || r.candidate_id;
      return `- Job: "${jobTitle}" | Candidate: "${candidateName}" | Rank #${r.rank_position} | Overall: ${Math.round((r.overall_score || 0) * 100)}% | Skills: ${Math.round((r.skill_match_score || 0) * 100)}% | Explanation: ${r.explanation || 'N/A'}`;
    }).join('\n');

    return {
      candidates: candidatesWithRankings,
      jobs,
      rankings,
      formattedText: `
=== QUICK HIRE DATABASE CONTEXT ===
AVAILABLE JOBS (${jobs.length}):
${formattedJobs || 'No jobs uploaded yet.'}

CANDIDATES PROFILES (${candidates.length}):
${formattedCandidates || 'No candidate CVs uploaded yet.'}

RECENT RANKINGS (${rankings.length}):
${formattedRankings || 'No rankings computed yet.'}
===================================`,
    };
  } catch (err) {
    console.warn('[retrieveRagContext] Warning:', err);
    return { candidates: [], jobs: [], rankings: [], formattedText: 'DATABASE CONTEXT EMPTY' };
  }
}

// ============================================================
//  2. Local Query Handler – offline/fallback knowledge base
// ============================================================
function localQueryHandler(query, rag) {
  const q = query.toLowerCase().trim();
  const { candidates, jobs, rankings } = rag;

  // --- 1. System Specification, Architecture, Pipeline & Tech Stack ---
  if (/(pipeline|architecture|tech stack|technical stack|how does it work|how it works|system spec|srs|group 19|tesseract|ocr|spacy|pytorch|sentence\s*transformer|embeddings?)/i.test(q)) {
    return {
      text: `### **QUICK HIRE System Architecture & Pipeline**

**1. Upload & Ingestion Layer:**
- **Supported Formats:** PDF, JPEG, PNG (max 10MB per file, batches up to 50 files).
- **Job Descriptions:** Plain text format or structured job requirements.
- **Conversion:** Uses \`pdf2image\` and Poppler for high-resolution page rendering.

**2. Processing Pipeline:**
- **Image Enhancement:** Preprocessing for optimal OCR readability.
- **Tesseract OCR:** High-fidelity text extraction with an **80%+ accuracy target**.
- **PyTorch CNN:** Document layout and section analysis (segmenting header, experience, education, skills).
- **spaCy NLP Engine:** Named Entity Recognition (NER) for extracting technical skills, degrees, job titles, and experience duration.
- **SentenceTransformers:** Computes high-dimensional semantic vector embeddings for contextual matching.

**3. Matching & Ranking Engine:**
- **Cosine Similarity:** Computes contextual semantic alignment between candidate vectors and job requirement vectors.
- **Skill Matching:** Explicit verification of required and preferred skills.
- **Data & Storage:** PostgreSQL 13+ with vector extension, Django/FastAPI backend, React frontend, and LLM/Rasa recruitment assistant.`,
      candidates: [],
    };
  }

  // --- 2. Business Rules, Governance, Bias Mitigation & POPIA Compliance ---
  if (/(business rule|governance|br-001|br-002|br-004|br-006|br-009|br-010|bias|popia|privacy|gdpr|compliance|demographic)/i.test(q)) {
    return {
      text: `### **QUICK HIRE Business Rules & Governance (SRS Version 1.0)**

- **BR-001 & BR-002 (Access Control):** Only authenticated recruiters can upload CVs and trigger ranking; system administrators oversee account access and system configuration.
- **BR-004 (Ranking Composition):** Ranking is driven by **semantic similarity (minimum 60% weight)** combined with explicit skill matching.
- **BR-006 (Factor Transparency):** Every ranking calculation provides clear factor explanations detailing semantic and skill match components.
- **BR-009 (Bias Prevention):** Strictly eliminates demographic factors (age, race, gender, nationality, physical address) from all similarity and scoring calculations.
- **BR-010 (Human-in-the-Loop):** System ranking is strictly advisory. Recruiters retain full decision-making authority for final candidate selection.
- **Regulatory Compliance:** Fully adheres to the South African **Protection of Personal Information Act (POPIA)** and strict data deletion and retention standards.`,
      candidates: [],
    };
  }

  // --- 3. App Guidance, System Navigation & Performance Constraints ---
  if (/(how to|guide|navigate|upload cv|export|report|filters?|constraints?|performance|sla|seconds?|limit)/i.test(q)) {
    return {
      text: `### **QUICK HIRE System Navigation & Performance Constraints**

**Feature Navigation:**
- **CV Upload:** Navigate to *Upload CVs* to batch upload up to 50 PDF/PNG/JPEG files (max 10MB each).
- **Job Ingestion:** Define or select target job descriptions with required/preferred skills.
- **Dashboard & Ranking:** Filter candidates by match score, minimum experience, and department.
- **Export Reports:** Generate and download PDF or Excel (.xlsx) ranking summary reports directly from the Dashboard.

**Performance & System SLA:**
- **CV Ingestion & Processing:** Under **30 seconds** per CV pipeline execution.
- **Ranking Engine:** Evaluates and ranks up to **1,000 candidates in under 10 seconds**.
- **Chatbot Response Time:** Immediate structured feedback under **3 seconds**.`,
      candidates: [],
    };
  }

  // --- 4. Candidate Comparison Queries (Side-by-side comparison) ---
  if (/compare|versus| vs |side by side/i.test(q)) {
    // Find mentioned candidates or take top 2-3
    const matched = candidates.filter(c => q.includes(c.name.toLowerCase()));
    const compCands = matched.length >= 2 ? matched.slice(0, 3) : candidates.slice(0, 2);

    if (compCands.length >= 2) {
      let tableRows = compCands.map(c => {
        const sd = c.structured_data || {};
        const skills = (sd.all_skills || sd.skills?.technical || []).slice(0, 4).join(', ') || 'N/A';
        const exp = `${sd.total_experience_years ?? sd.years_experience ?? 0} yrs`;
        const edu = sd.education?.degree || sd.education_history?.[0]?.degree || 'N/A';
        const score = c.bestRank ? `${Math.round(c.bestRank.overall_score * 100)}% (#${c.bestRank.rank_position})` : 'Unranked';
        return `| **${c.name}** | ${score} | ${exp} | ${edu} | ${skills} |`;
      }).join('\n');

      return {
        text: `### **Candidate Comparison**

| Candidate | Match Score | Experience | Degree | Core Skills |
| :--- | :--- | :--- | :--- | :--- |
${tableRows}

**Key Observations:**
- **Top Match:** **${compCands[0].name}** offers strong semantic alignment and verifiable skill match.
- **Experience Comparison:** ${compCands.map(c => `${c.name} (${c.structured_data?.total_experience_years || 0} yrs)`).join(' vs. ')}.
- **Recommendation:** Review portfolio or schedule preliminary screening based on required domain qualifications.`,
        candidates: compCands.map(c => ({
          id: c.id,
          name: c.name,
          relevance_score: c.bestRank?.overall_score || 0.85,
          years_experience: c.structured_data?.total_experience_years || 0,
          all_skills: c.structured_data?.all_skills || [],
        })),
      };
    }
  }

  // --- 5. Candidate Ranking Explanations ---
  if (/(why|explain|factor|score breakdown|how was.*ranked|why is.*ranked)/i.test(q)) {
    const nameMatch = candidates.find(c => q.includes(c.name.toLowerCase()));
    const target = nameMatch || candidates[0];

    if (target && target.bestRank) {
      const r = target.bestRank;
      return {
        text: `### **Ranking Score Breakdown for ${target.name}**

- **Overall Match Score:** **${Math.round((r.overall_score || 0) * 100)}%** (Rank **#${r.rank_position}**)
- **Semantic Vector Similarity:** **${Math.round((r.similarity_score || r.overall_score || 0.8) * 100)}%** (SentenceTransformers contextual match against Job Description)
- **Explicit Skill Match:** **${Math.round((r.skill_match_score || 0.85) * 100)}%** (Exact keyword and NLP entity validation)
- **Explanation:** ${r.explanation || 'Demonstrates strong alignment with core requirements, relevant domain experience, and matching technical skillset.'}

**Recruiter Actionable Follow-up:**
- You can adjust the semantic vs. skill matching weights or filter by minimum required years of experience in the dashboard.`,
        candidates: [{
          id: target.id,
          name: target.name,
          relevance_score: target.bestRank?.overall_score || 0.9,
          years_experience: target.structured_data?.total_experience_years || 0,
          all_skills: target.structured_data?.all_skills || [],
        }],
      };
    }
  }

  // --- 6. Recent Activity / Upload / Summary queries ---
  if (/(recent|activity|upload|summary|last week|this week|today|yesterday)/i.test(q)) {
    const recentUploads = candidates.filter(c => {
      const d = new Date(c.created_at);
      const weekAgo = new Date();
      weekAgo.setDate(weekAgo.getDate() - 7);
      return d > weekAgo;
    });

    let text = `### **System Activity Summary**\n\n`;
    text += `- **Total Candidates in System:** ${candidates.length}\n`;
    text += `- **Recent CV Uploads (Last 7 Days):** ${recentUploads.length}\n`;
    text += `- **Active Job Descriptions:** ${jobs.length}\n`;
    text += `- **Rankings Computed:** ${rankings.length}\n`;

    if (recentUploads.length > 0) {
      text += `\n**Recently Ingested Candidates:**\n` + recentUploads.slice(0, 3).map(c => `- **${c.name}** (${c.email || 'N/A'})`).join('\n');
    }

    return {
      text,
      candidates: recentUploads.slice(0, 3).map(c => ({
        id: c.id,
        name: c.name,
        relevance_score: c.bestRank?.overall_score || 0.5,
        years_experience: c.structured_data?.total_experience_years || 0,
        all_skills: c.structured_data?.all_skills || [],
      })),
    };
  }

  // --- 7. Top Candidates Queries ---
  const topMatch = q.match(/top\s*(\d+)?\s*(candidates?)?\s*(for|of)?\s*(.+)?/i);
  if (topMatch || /(top candidates?|best candidates?|highest match)/i.test(q)) {
    const limit = topMatch ? (parseInt(topMatch[1]) || 5) : 5;
    const jobTitle = topMatch && topMatch[4] ? topMatch[4].trim() : null;
    let filtered = candidates;

    if (jobTitle) {
      const matchedJobs = jobs.filter(j => j.title.toLowerCase().includes(jobTitle.toLowerCase()));
      if (matchedJobs.length) {
        const jobIds = matchedJobs.map(j => j.id);
        const rankedCandIds = rankings.filter(r => jobIds.includes(r.job_id)).map(r => r.candidate_id);
        filtered = candidates.filter(c => rankedCandIds.includes(c.id));
      }
    }

    if (!filtered.length) filtered = candidates;
    filtered.sort((a, b) => (b.bestRank?.overall_score || 0) - (a.bestRank?.overall_score || 0));
    const top = filtered.slice(0, limit);

    if (top.length === 0) {
      return { text: `No candidates found${jobTitle ? ` for "${jobTitle}"` : ''} in the database.`, candidates: [] };
    }

    const cardCandidates = top.map(c => ({
      id: c.id,
      name: c.name,
      relevance_score: c.bestRank?.overall_score || 0.5,
      years_experience: c.structured_data?.total_experience_years || 0,
      all_skills: c.structured_data?.all_skills || [],
    }));

    const text = `### **Top ${top.length} Candidates${jobTitle ? ` for "${jobTitle}"` : ''}**\n\n` +
      top.map((c, i) => {
        const score = c.bestRank ? `${Math.round(c.bestRank.overall_score * 100)}% match` : 'Pending ranking';
        const exp = c.structured_data?.total_experience_years || 0;
        const skills = (c.structured_data?.all_skills || []).slice(0, 3).join(', ') || 'N/A';
        return `${i + 1}. **${c.name}** — ${score} | ${exp} yrs exp | *Skills:* ${skills}`;
      }).join('\n') +
      `\n\n*Note: Recommendations are advisory (BR-010). Final hiring authority rests with the recruiter.*`;

    return { text, candidates: cardCandidates };
  }

  // --- 8. Search by Skills or Role ---
  const skillKeywords = ['python', 'java', 'javascript', 'react', 'node', 'sql', 'c++', 'aws', 'docker', 'kubernetes', 'typescript', 'angular', 'vue', 'php', 'ruby', 'go', 'rust', 'swift', 'kotlin', 'scala', 'perl', 'html', 'css', 'git', 'ci/cd', 'machine learning', 'ai', 'nlp', 'backend', 'frontend', 'fullstack', 'devops', 'cloud', 'security'];
  const foundSkills = skillKeywords.filter(skill => q.includes(skill));

  if (foundSkills.length > 0) {
    const matched = candidates.filter(c => {
      const skills = (c.structured_data?.all_skills || []).map(s => s.toLowerCase());
      return foundSkills.some(fs => skills.some(s => s.includes(fs) || fs.includes(s)));
    });

    if (matched.length > 0) {
      const topMatched = matched.slice(0, 5);
      const cardCandidates = topMatched.map(c => ({
        id: c.id,
        name: c.name,
        relevance_score: c.bestRank?.overall_score || 0.8,
        years_experience: c.structured_data?.total_experience_years || 0,
        all_skills: c.structured_data?.all_skills || [],
      }));

      const text = `### **Candidates Matching Skills: ${foundSkills.join(', ')}**\n\n` +
        `Found **${matched.length} candidate(s)** with matching competencies:\n\n` +
        topMatched.map((c, i) => {
          const exp = c.structured_data?.total_experience_years || 0;
          const skills = (c.structured_data?.all_skills || []).slice(0, 4).join(', ');
          return `${i + 1}. **${c.name}** (${exp} yrs exp) — *Skills:* ${skills}`;
        }).join('\n');

      return { text, candidates: cardCandidates };
    }
  }

  // --- 9. Default Overview ---
  return {
    text: `### **QUICK HIRE AI Recruitment Assistant**\n\n` +
      `I am ready to assist you with candidate screening, ranking explanations, side-by-side candidate comparisons, and system architecture guidance.\n\n` +
      `**Current Database Snapshot:**\n` +
      `- **Total Candidates Ingested:** ${candidates.length}\n` +
      `- **Active Job Descriptions:** ${jobs.length}\n` +
      `- **Rankings Evaluated:** ${rankings.length}\n\n` +
      `**Try asking:**\n` +
      `- *"Show top candidates for Senior Developer"*\n` +
      `- *"Explain the score for [Candidate Name]"*\n` +
      `- *"Compare candidate A and candidate B"*\n` +
      `- *"What is the QUICK HIRE processing pipeline and tech stack?"*\n` +
      `- *"What are the business rules for bias prevention and ranking?"*`,
    candidates: candidates.slice(0, 3).map(c => ({
      id: c.id,
      name: c.name,
      relevance_score: c.bestRank?.overall_score || 0.5,
      years_experience: c.structured_data?.total_experience_years || 0,
      all_skills: c.structured_data?.all_skills || [],
    })),
  };
}

// ============================================================
//  3. Multi-Turn History
// ============================================================
async function fetchChatHistory(sessionId) {
  if (!sessionId) return [];
  try {
    const { data, error } = await supabase
      .from('chat_logs')
      .select('role, message, query_text, response_text, created_at')
      .eq('session_id', sessionId)
      .order('created_at', { ascending: true })
      .limit(20);

    if (error) {
      console.warn('[fetchChatHistory] Supabase error:', error);
      return [];
    }

    const historyItems = [];
    (data || []).forEach((log) => {
      if (log.role === 'user' && log.query_text) {
        historyItems.push({ role: 'user', parts: [{ text: log.query_text }] });
      } else if (log.role === 'assistant' && log.response_text) {
        historyItems.push({ role: 'model', parts: [{ text: log.response_text }] });
      } else if (log.role === 'user' && log.message) {
        historyItems.push({ role: 'user', parts: [{ text: log.message }] });
      } else if (log.role === 'assistant' && log.message) {
        historyItems.push({ role: 'model', parts: [{ text: log.message }] });
      }
    });
    return historyItems;
  } catch (_) {
    return [];
  }
}

// ============================================================
//  4. Main send function
// ============================================================
export const sendMessageWithGemini = async (message, sessionId, userId = null, companyId = null) => {
  const prompt = (message || '').trim();
  if (!prompt) return { type: 'text', text: 'Please enter a query.' };

  const rag = await retrieveRagContext(companyId);

  let responseText = '';
  let isRateLimited = false;
  let usedFallback = false;

  try {
    const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

    const historyItems = await fetchChatHistory(sessionId);

    const chat = ai.chats.create({
      model: 'gemini-2.0-flash',
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION}\n\n${rag.formattedText}`,
      },
      history: historyItems,
    });

    const result = await chat.sendMessage({ message: prompt });
    responseText = result.text || 'I analyzed the database context, but no textual response was generated.';
  } catch (geminiErr) {
    const errStr = String(geminiErr?.message || geminiErr || '');
    console.warn('[sendMessageWithGemini] Gemini SDK Exception:', errStr);

    if (errStr.includes('429') || errStr.includes('RESOURCE_EXHAUSTED') || errStr.toLowerCase().includes('rate limit')) {
      isRateLimited = true;
      usedFallback = true;
    } else {
      usedFallback = true;
    }
  }

  // If Gemini failed or rate-limited, use local handler
  if (usedFallback) {
    const localResult = localQueryHandler(prompt, rag);
    responseText = localResult.text;
    let candidateCards = localResult.candidates || [];
    if (candidateCards.length === 0 && rag.candidates.length > 0) {
      candidateCards = rag.candidates.slice(0, 3).map(c => ({
        id: c.id,
        name: c.name,
        relevance_score: c.bestRank?.overall_score || 0.5,
        years_experience: c.structured_data?.total_experience_years || 0,
        all_skills: c.structured_data?.all_skills || [],
      }));
    }
    try {
      await supabase.from('chat_logs').insert({
        user_id: userId,
        session_id: sessionId,
        role: 'assistant',
        message: responseText,
        query_text: prompt,
        response_text: responseText,
        intent: usedFallback ? 'fallback-local' : 'gemini-2.0-flash-rag',
        confidence: usedFallback ? 0.5 : 0.95,
        created_at: new Date().toISOString(),
      });
    } catch (auditErr) {
      console.warn('[sendMessageWithGemini] chat_logs write warning:', auditErr);
    }

    return {
      type: 'text',
      text: responseText,
      session_id: sessionId,
      is_rate_limit: isRateLimited,
      candidates: candidateCards,
    };
  }

  // Gemini succeeded – store and return
  try {
    await supabase.from('chat_logs').insert({
      user_id: userId,
      session_id: sessionId,
      role: 'assistant',
      message: responseText,
      query_text: prompt,
      response_text: responseText,
      intent: 'gemini-2.0-flash-rag',
      confidence: 0.95,
      created_at: new Date().toISOString(),
    });
  } catch (auditErr) {
    console.warn('[sendMessageWithGemini] chat_logs write warning:', auditErr);
  }

  let candidateCards = undefined;
  const isCandQuery = /candidate|top|rank|developer|engineer|skills|experience/i.test(prompt);
  if (isCandQuery && rag.candidates.length > 0) {
    const mentioned = rag.candidates.filter(c => responseText.includes(c.name));
    if (mentioned.length) {
      candidateCards = mentioned.slice(0, 3).map(c => ({
        id: c.id,
        name: c.name,
        relevance_score: c.bestRank?.overall_score || 0.5,
        years_experience: c.structured_data?.total_experience_years || 0,
        all_skills: c.structured_data?.all_skills || [],
      }));
    } else {
      const sorted = [...rag.candidates].sort((a,b) => (b.bestRank?.overall_score || 0) - (a.bestRank?.overall_score || 0));
      candidateCards = sorted.slice(0, 3).map(c => ({
        id: c.id,
        name: c.name,
        relevance_score: c.bestRank?.overall_score || 0.5,
        years_experience: c.structured_data?.total_experience_years || 0,
        all_skills: c.structured_data?.all_skills || [],
      }));
    }
  }

  return {
    type: 'text',
    text: responseText,
    session_id: sessionId,
    is_rate_limit: isRateLimited,
    candidates: candidateCards,
  };
};

// ============================================================
//  Exported service
// ============================================================
const chatbotServiceExport = {
  sendMessage: async (message, sessionId, userId = null, companyId = null) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const fnUrl = process.env.REACT_APP_SUPABASE_URL ? `${process.env.REACT_APP_SUPABASE_URL}/functions/v1/chatbot` : null;
      if (fnUrl && session) {
        const res = await fetch(fnUrl, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${session.access_token}`,
            'Content-Type': 'application/json',
            apikey: process.env.REACT_APP_SUPABASE_ANON_KEY || '',
          },
          body: JSON.stringify({ message, session_id: sessionId }),
        });
        if (res.ok) {
          const edgeJson = await res.json();
          if (edgeJson && edgeJson.text) return edgeJson;
        }
      }
    } catch (_) {}

    return await sendMessageWithGemini(message, sessionId, userId, companyId);
  },

  getConversationHistory: async (userId, sessionId) => {
    try {
      let query = supabase
        .from('chat_logs')
        .select('*')
        .order('created_at', { ascending: true });
      if (userId) query = query.eq('user_id', userId);
      if (sessionId) query = query.eq('session_id', sessionId);
      const { data, error } = await query;
      if (error) {
        console.warn('[getConversationHistory] Supabase error:', error);
        return [];
      }
      return (data || []).map((log) => ({
        id: 'db-' + log.id,
        from: log.role === 'user' ? 'user' : 'bot',
        text: log.message || log.query_text || log.response_text || '',
        parts: log.response_parts || [],
        suggestions: log.suggestions || [],
        time: new Date(log.created_at).getTime(),
      }));
    } catch (_) {
      return [];
    }
  },

  storeUserMessage: async ({ userId, sessionId, message }) => {
    try {
      await supabase.from('chat_logs').insert({
        user_id: userId,
        session_id: sessionId,
        role: 'user',
        message: message,
        query_text: message,
        created_at: new Date().toISOString(),
      });
    } catch (_) {}
  },

  storeBotReply: async ({ userId, sessionId, message, responseParts, suggestions }) => {
    try {
      await supabase.from('chat_logs').insert({
        user_id: userId,
        session_id: sessionId,
        role: 'assistant',
        message: message,
        response_text: message,
        response_parts: responseParts || null,
        suggestions: suggestions || null,
        created_at: new Date().toISOString(),
      });
    } catch (_) {}
  },
};

export default chatbotServiceExport;