export const activityService = {
  getFeed: async (limit = 8) => {
    let dbLogs = [];
    // Try to fetch from Supabase
    try {
      const { data, error } = await supabase
        .from('audit_logs')
        .select('*, users(username, email, first_name, last_name)')
        .order('created_at', { ascending: false })
        .limit(limit * 2); // fetch extra to have enough after filtering
      if (!error && data) {
        dbLogs = data;
      }
    } catch (_) {
      // ignore db errors
    }

    // Fetch local cache logs
    let localLogs = [];
    try {
      const raw = localStorage.getItem(LOCAL_AUDIT_KEY);
      if (raw) {
        localLogs = JSON.parse(raw);
      }
    } catch (_) {}

    // Combine and deduplicate by id (or fallback to timestamp+action)
    const seen = new Set();
    const combined = [];
    // Local logs first (most recent)
    [...localLogs, ...dbLogs].forEach(item => {
      const key = item.id || `${item.created_at || ''}-${item.action || ''}`;
      if (!seen.has(key)) {
        seen.add(key);
        combined.push(item);
      }
    });

    // If still empty, seed with initial logs (from the INITIAL_SEED_LOGS in this file)
    if (combined.length === 0) {
      // We can import or use the same seed logs defined earlier in this file
      // They are defined as INITIAL_SEED_LOGS at the top of the file
      // Use them and also store them in local cache for future
      const seedLogs = INITIAL_SEED_LOGS || [
        {
          id: 'seed-log-1',
          created_at: new Date(Date.now() - 5 * 60 * 1000).toISOString(),
          user: 'System',
          action: 'Login',
          ip_address: '127.0.0.1',
          details: { summary: 'System initialized' }
        },
        {
          id: 'seed-log-2',
          created_at: new Date(Date.now() - 10 * 60 * 1000).toISOString(),
          user: 'System',
          action: 'Create',
          ip_address: '127.0.0.1',
          details: { summary: 'Database tables created' }
        }
      ];
      seedLogs.forEach(log => {
        combined.push(log);
        // Also store in localStorage so next time we have them
        try {
          const existing = JSON.parse(localStorage.getItem(LOCAL_AUDIT_KEY) || '[]');
          if (!existing.some(e => e.id === log.id)) {
            localStorage.setItem(LOCAL_AUDIT_KEY, JSON.stringify([log, ...existing].slice(0, 200)));
          }
        } catch (_) {}
      });
    }

    // Sort by created_at descending
    combined.sort((a, b) => new Date(b.created_at || b.timestamp).getTime() - new Date(a.created_at || a.timestamp).getTime());

    // Take only the limit
    const feedItems = combined.slice(0, limit);

    // Map to the format expected by the dashboard
    return feedItems.map((l) => {
      const d = new Date(l.created_at || l.timestamp || Date.now());
      const mins = Math.floor((Date.now() - d.getTime()) / 60000);
      let time = d.toLocaleString();
      if (mins < 60) time = `${mins} minute${mins === 1 ? '' : 's'} ago`;
      else if (mins < 1440) time = `${Math.floor(mins / 60)} hour${Math.floor(mins / 60) === 1 ? '' : 's'} ago`;
      else time = `${Math.floor(mins / 1440)} day${Math.floor(mins / 1440) === 1 ? '' : 's'} ago`;

      // Try to get user name from the log
      const user = l.users?.username || l.users?.email || l.user || l.user_id || 'System';
      const action = l.action || 'Action';
      const summary = l.details?.summary || (typeof l.details === 'string' ? l.details : JSON.stringify(l.details || {}).slice(0, 120));

      return {
        time,
        title: `${user} — ${action}`,
        desc: summary,
        icon: 'clipboard-list',
        type: 'info',
      };
    });
  },
};

